          onProgress: (current, total, message) =>
            storage.jobs.updateProgress(job.id, workerId, current, total, message),
        });
      } finally {
        if (!storage.getItem(item.id)?.thumbnailPath) {
          thumbnailCursor = 0;
          thumbnailBackfillDone = false;
